#include "tensor_layout.h"
#include <assert.h>
#include <stddef.h>
#include <stdio.h>
int main(void){size_t shape[]={3,4,5};TensorLayout row,col;assert(tensor_layout_row_major(&row,shape,3));assert(tensor_layout_column_major(&col,shape,3));assert(tensor_layout_validate(&row)&&tensor_layout_validate(&col));assert(tensor_layout_is_row_major_contiguous(&row));assert(!tensor_layout_is_column_major_contiguous(&row));assert(tensor_layout_is_column_major_contiguous(&col));size_t idx[]={2,3,4},off=0;assert(tensor_layout_offset(&row,idx,&off)&&off==59);assert(tensor_layout_offset(&col,idx,&off)&&off==59);size_t p[]={1,0,2};TensorLayout tr;assert(tensor_layout_permute(&row,p,&tr));size_t tidx[]={3,2,4};assert(tensor_layout_offset(&tr,tidx,&off)&&off==59);assert(!tensor_layout_is_row_major_contiguous(&tr));TensorLayout slice;assert(tensor_layout_slice(&row,1,1,2,2,&slice));size_t sidx[]={2,1,4};assert(tensor_layout_offset(&slice,sidx,&off)&&off==59);size_t total=0;assert(tensor_layout_total_elements(&slice,&total)&&total==30);size_t bad_perm[]={0,0,2};assert(!tensor_layout_permute(&row,bad_perm,&tr));assert(!tensor_layout_slice(&row,1,3,2,1,&slice));puts("Tensor Layout tests passed");return 0;}
